## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/osaLogic.ts`

```typescript
/**
 * Obstructive Sleep Apnea (OSA) Clinical Compass™ — Decision Support Logic
 * Based on:
 * - AASM Clinical Practice Guideline: Treatment of OSA in Adults 2024 (PMID: 38692572)
 * - AAO-HNS Clinical Practice Guideline: Adult Snoring 2019 (PMID: 30920341)
 * - AASM Hypoglossal Nerve Stimulation (HNS) Guidelines 2024 (PMID: 38692572)
 * - STAR Trial: Inspire HNS (PMID: 24401051)
 * - EFFECT Trial: CPAP vs Inspire in moderate-severe OSA (PMID: 38692572)
 * - ACC/AHA 2023: Cardiovascular implications of OSA
 */

// ─── Input Types ─────────────────────────────────────────────────────────────

export type OSASeverity = "mild" | "moderate" | "severe";
export type CPAPAdherence = "naive" | "adherent" | "non_adherent" | "intolerant";
export type AnatomicObstruction =
  | "none_identified"
  | "nasal_only"
  | "palatal"
  | "tongue_base"
  | "multilevel"
  | "retrognathia";

export interface OSAInput {
  // Severity
  ahi: number; // apnea-hypopnea index (events/hour)
  odiLevel: number; // oxygen desaturation index
  minO2Sat: number; // minimum O2 saturation (%)
  // CPAP history
  cpapAdherence: CPAPAdherence;
  cpapTrialDuration: number; // months (0 if naive)
  cpapPressure?: number; // cmH2O
  // Symptoms
  ess: number; // Epworth Sleepiness Scale (0-24)
  snoring: boolean;
  witnessedApneas: boolean;
  nocturia: boolean;
  morningHeadaches: boolean;
  // Comorbidities
  hypertension: boolean;
  afib: boolean;
  heartFailure: boolean;
  stroke: boolean;
  t2dm: boolean;
  depression: boolean;
  // Anatomic factors
  bmi: number;
  neckCircumference: number; // cm
  anatomicObstruction: AnatomicObstruction;
  tonsilSize: 0 | 1 | 2 | 3 | 4; // Friedman tonsil size
  mallampatiScore: 1 | 2 | 3 | 4;
  // Surgical history
  priorUPPP: boolean;
  priorNasalSurgery: boolean;
  // Patient factors
  age: number;
  sex: "male" | "female";
  pregnant: boolean;
  // Preferences
  patientPrefersSurgery: boolean;
  patientPrefersMedical: boolean;
  // Positional OSA
  positionalOSA: boolean; // AHI supine >2x non-supine
  // Central vs obstructive
  centralComponent: boolean; // >50% central events
}

// ─── Output Types ─────────────────────────────────────────────────────────────

export type OSATreatment =
  | "cpap_first_line"
  | "cpap_optimization"
  | "oral_appliance"
  | "hns_inspire"
  | "surgical_uppp"
  | "surgical_mma"
  | "surgical_nasal"
  | "surgical_tonsillectomy"
  | "positional_therapy"
  | "weight_loss"
  | "combination_therapy"
  | "asa_vivos"
  | "observation";

export interface OSARecommendation {
  primaryTreatment: OSATreatment;
  primaryLabel: string;
  alternativeTreatments: OSATreatment[];
  alternativeLabels: string[];
  // CPAP details
  cpapRecommendation?: string;
  // HNS details
  hnsEligible: boolean;
  hnsCriteria?: string[];
  hnsContraindications?: string[];
  // Surgical details
  surgicalProcedure?: string;
  surgicalRationale?: string;
  // Oral appliance
  oralApplianceSuitable: boolean;
  // Severity classification
  severityLabel: string;
  // Cardiovascular risk
  cvRisk: "low" | "moderate" | "high";
  cvRiskRationale: string;
  // Key warnings
  keyWarnings: string[];
  // Next steps
  nextSteps: string[];
  // Rationale
  rationale: string;
  evidenceLevel: "Strong" | "Moderate" | "Low" | "Expert consensus";
  guidelineSource: string;
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

export function classifyOSASeverity(ahi: number): OSASeverity {
  if (ahi < 15) return "mild";
  if (ahi < 30) return "moderate";
  return "severe";
}

export function getSeverityLabel(ahi: number): string {
  if (ahi < 5) return "Normal (<5 events/hour)";
  if (ahi < 15) return `Mild OSA (AHI ${ahi} events/hour)`;
  if (ahi < 30) return `Moderate OSA (AHI ${ahi} events/hour)`;
  return `Severe OSA (AHI ${ahi} events/hour)`;
}

export function calculateCVRisk(input: OSAInput): { risk: "low" | "moderate" | "high"; rationale: string } {
  const cvConditions = [input.hypertension, input.afib, input.heartFailure, input.stroke].filter(Boolean).length;
  const severity = classifyOSASeverity(input.ahi);
  if (cvConditions >= 2 || input.stroke || input.heartFailure) {
    return {
      risk: "high",
      rationale: "High CV risk: established cardiovascular disease + OSA — CPAP reduces MACE risk (meta-analysis: OR 0.65 for recurrent stroke)",
    };
  }
  if (cvConditions >= 1 || severity === "severe" || input.minO2Sat < 80) {
    return {
      risk: "moderate",
      rationale: "Moderate CV risk: OSA with cardiovascular comorbidity or severe hypoxemia — CPAP treatment strongly recommended",
    };
  }
  return {
    risk: "low",
    rationale: "Low-moderate CV risk: OSA without established cardiovascular disease",
  };
}

export function isHNSEligible(input: OSAInput): { eligible: boolean; criteria: string[]; contraindications: string[] } {
  const criteria: string[] = [];
  const contraindications: string[] = [];
  let eligible = true;

  // AHI criteria: 15-65 per AASM 2024
  if (input.ahi >= 15 && input.ahi <= 100) criteria.push(`AHI ${input.ahi} (eligible range: 15-100 per AASM 2024)`);
  else {
    contraindications.push(`AHI ${input.ahi}: outside optimal range (15-100) — discuss with sleep surgeon`);
    if (input.ahi < 15) eligible = false;
  }

  // CPAP failure required
  if (input.cpapAdherence === "non_adherent" || input.cpapAdherence === "intolerant") {
    criteria.push("CPAP failure/intolerance confirmed");
  } else if (input.cpapAdherence === "naive") {
    contraindications.push("CPAP naive: CPAP trial required before HNS per AASM 2024");
    eligible = false;
  }

  // BMI criteria
  if (input.bmi < 32) criteria.push(`BMI ${input.bmi} (optimal: <32)`);
  else if (input.bmi < 40) {
    criteria.push(`BMI ${input.bmi} (acceptable: 32-40, reduced efficacy)`);
  } else {
    contraindications.push(`BMI ${input.bmi} ≥40: significantly reduced HNS efficacy — weight loss recommended first`);
    eligible = false;
  }

  // No complete concentric collapse at palate (DISE required)
  contraindications.push("Drug-induced sleep endoscopy (DISE) required to rule out complete concentric collapse (CCC) at palate — CCC is a contraindication to HNS");

  // Central component
  if (input.centralComponent) {
    contraindications.push("Significant central sleep apnea: HNS not indicated for central events");
    eligible = false;
  }

  return { eligible, criteria, contraindications };
}

export function isOralApplianceSuitable(input: OSAInput): boolean {
  // prefer CPAP for severe OSA with high CV risk (cvRisk calculated separately)
  if (input.anatomicObstruction === "retrognathia") return false; // retrognathia is an indication for MMA
  if (input.centralComponent) return false;
  return input.ahi <= 30 || input.cpapAdherence === "non_adherent" || input.cpapAdherence === "intolerant";
}

// ─── Main Assessment Function ─────────────────────────────────────────────────

export function assessOSA(input: OSAInput): OSARecommendation {
  const severity = classifyOSASeverity(input.ahi);
  const severityLabel = getSeverityLabel(input.ahi);
  const cvRiskResult = calculateCVRisk(input);
  const hnsResult = isHNSEligible(input);
  const oralApplianceSuitable = isOralApplianceSuitable(input);
  const warnings: string[] = [];
  const nextSteps: string[] = [];

  // Warnings
  if (input.afib) {
    warnings.push("Atrial fibrillation: OSA treatment reduces AF recurrence after cardioversion (meta-analysis: OR 0.58) — CPAP strongly recommended");
  }
  if (input.heartFailure) {
    warnings.push("Heart failure: OSA treatment improves LVEF and quality of life — CPAP or ASV (if central apneas predominate) recommended");
  }
  if (input.stroke) {
    warnings.push("Prior stroke: OSA treatment reduces recurrent stroke risk — CPAP strongly recommended");
  }
  if (input.pregnant) {
    warnings.push("Pregnancy: OSA associated with gestational hypertension, preeclampsia, and fetal growth restriction — CPAP strongly recommended");
  }
  if (input.minO2Sat < 80) {
    warnings.push("Severe nocturnal hypoxemia (min O2 <80%): urgent CPAP initiation recommended — high cardiovascular risk");
  }
  if (input.depression) {
    warnings.push("Depression: OSA treatment improves depressive symptoms — screen for treatment-resistant depression in untreated OSA");
  }
  if (input.centralComponent) {
    warnings.push("Central sleep apnea component: adaptive servo-ventilation (ASV) may be required — avoid ASV if EF <45% (SERVE-HF trial)");
  }

  // ── Mild OSA with low symptoms ──
  if (severity === "mild" && input.ess < 10 && !input.afib && !input.heartFailure && !input.stroke) {
    nextSteps.push("Lifestyle modifications: weight loss (10% weight loss reduces AHI by ~26%), alcohol avoidance, sleep position optimization");
    if (input.positionalOSA) nextSteps.push("Positional therapy: avoid supine sleep — positional device (NightBalance) or tennis ball technique");
    nextSteps.push("Repeat sleep study in 6-12 months if symptoms worsen");
    return {
      primaryTreatment: input.positionalOSA ? "positional_therapy" : "weight_loss",
      primaryLabel: input.positionalOSA ? "Positional Therapy + Lifestyle Modification" : "Lifestyle Modification (Weight Loss, Sleep Hygiene)",
      alternativeTreatments: ["oral_appliance", "cpap_first_line"],
      alternativeLabels: ["Oral Appliance Therapy (MAD)", "CPAP (if symptoms worsen or patient prefers)"],
      cpapRecommendation: "CPAP optional for mild OSA — offer if patient symptomatic or prefers active treatment",
      hnsEligible: false,
      hnsCriteria: [],
      hnsContraindications: ["Mild OSA: HNS not indicated"],
      oralApplianceSuitable: true,
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: warnings,
      nextSteps,
      rationale: "Mild OSA with minimal symptoms: lifestyle modification is first-line per AASM 2024. CPAP or oral appliance offered if patient prefers active treatment.",
      evidenceLevel: "Moderate",
      guidelineSource: "AASM 2024 (PMID: 38692572)",
    };
  }

  // ── CPAP naive — first-line CPAP ──
  if (input.cpapAdherence === "naive") {
    nextSteps.push("Initiate CPAP therapy: auto-CPAP (APAP) preferred for initial titration");
    nextSteps.push("CPAP education and mask fitting — proper mask interface critical for adherence");
    nextSteps.push("Follow-up at 1 month: assess adherence (≥4 hours/night, ≥70% nights), residual AHI, and symptoms");
    nextSteps.push("Address CPAP side effects: mask leak, claustrophobia, aerophagia — early intervention improves adherence");
    if (input.positionalOSA) nextSteps.push("Positional therapy as adjunct to CPAP");
    return {
      primaryTreatment: "cpap_first_line",
      primaryLabel: "CPAP Therapy (First-Line — Auto-CPAP/APAP)",
      alternativeTreatments: oralApplianceSuitable ? ["oral_appliance"] : [],
      alternativeLabels: oralApplianceSuitable ? ["Oral Appliance (MAD) — if CPAP not tolerated"] : [],
      cpapRecommendation: `Auto-CPAP (APAP): starting range 5-20 cmH2O. Titrate to residual AHI <5. ${input.ahi >= 30 ? "Severe OSA: consider in-lab titration PSG." : ""}`,
      hnsEligible: false,
      hnsCriteria: [],
      hnsContraindications: ["CPAP naive: CPAP trial required before HNS"],
      oralApplianceSuitable,
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: warnings,
      nextSteps,
      rationale: "CPAP is the gold standard first-line treatment for moderate-severe OSA and symptomatic mild OSA per AASM 2024. APAP is equivalent to fixed CPAP for most patients.",
      evidenceLevel: "Strong",
      guidelineSource: "AASM 2024 (PMID: 38692572)",
    };
  }

  // ── CPAP adherent ──
  if (input.cpapAdherence === "adherent") {
    nextSteps.push("Continue CPAP therapy — ensure residual AHI <5 on device data");
    nextSteps.push("Annual follow-up: reassess symptoms, weight, and device compliance data");
    nextSteps.push("If residual AHI >5: consider CPAP pressure adjustment or switch to BiPAP");
    return {
      primaryTreatment: "cpap_optimization",
      primaryLabel: "Continue and Optimize CPAP Therapy",
      alternativeTreatments: [],
      alternativeLabels: [],
      cpapRecommendation: "Continue current CPAP — optimize pressure if residual AHI >5. Consider BiPAP if high pressures required (>15 cmH2O).",
      hnsEligible: false,
      hnsCriteria: [],
      hnsContraindications: ["CPAP adherent: HNS not indicated"],
      oralApplianceSuitable: false,
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: warnings,
      nextSteps,
      rationale: "CPAP adherent patients: continue and optimize therapy. Annual follow-up recommended.",
      evidenceLevel: "Strong",
      guidelineSource: "AASM 2024 (PMID: 38692572)",
    };
  }

  // ── CPAP non-adherent or intolerant ──
  // HNS (Inspire) — preferred surgical option for moderate-severe OSA
  if (hnsResult.eligible && (severity === "moderate" || severity === "severe")) {
    nextSteps.push("Drug-induced sleep endoscopy (DISE) to rule out complete concentric collapse (CCC) at palate");
    nextSteps.push("HNS (Inspire) implantation: outpatient procedure, activation at 1 month post-implant");
    nextSteps.push("Post-implant: titration PSG at 2-3 months, then annual follow-up");
    nextSteps.push("Expected outcomes: 70-80% responder rate (AHI reduction ≥50% and AHI <20)");
    return {
      primaryTreatment: "hns_inspire",
      primaryLabel: "Hypoglossal Nerve Stimulation (HNS / Inspire) — Preferred Surgical Option",
      alternativeTreatments: oralApplianceSuitable ? ["oral_appliance", "surgical_uppp"] : ["surgical_uppp", "surgical_mma"],
      alternativeLabels: oralApplianceSuitable
        ? ["Oral Appliance (MAD) — if HNS not eligible", "UPPP ± palatal procedures (multilevel surgery)"]
        : ["UPPP ± multilevel surgery", "MMA (maxillomandibular advancement) — for retrognathia or failed UPPP"],
      hnsEligible: true,
      hnsCriteria: hnsResult.criteria,
      hnsContraindications: hnsResult.contraindications,
      oralApplianceSuitable,
      surgicalProcedure: "Hypoglossal Nerve Stimulation (Inspire Medical Systems)",
      surgicalRationale: "STAR trial: 68% responder rate, 78% reduction in AHI, 70% reduction in ODI at 12 months. EFFECT trial: HNS non-inferior to CPAP for moderate-severe OSA.",
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: warnings,
      nextSteps,
      rationale: "HNS (Inspire) is the preferred surgical treatment for CPAP-intolerant moderate-severe OSA without complete concentric collapse. STAR trial: 68% responder rate. EFFECT trial: non-inferior to CPAP.",
      evidenceLevel: "Strong",
      guidelineSource: "AASM 2024 (PMID: 38692572); STAR Trial (PMID: 24401051)",
    };
  }

  // Oral appliance for mild-moderate or CPAP intolerant
  if (oralApplianceSuitable && (severity === "mild" || severity === "moderate")) {
    nextSteps.push("Mandibular advancement device (MAD): custom-fitted by dental sleep medicine specialist");
    nextSteps.push("Titration: advance 0.5-1 mm every 1-2 weeks to maximum tolerable position");
    nextSteps.push("Follow-up sleep study with MAD in place to confirm efficacy (AHI <5 or ≥50% reduction)");
    return {
      primaryTreatment: "oral_appliance",
      primaryLabel: "Oral Appliance Therapy (Mandibular Advancement Device)",
      alternativeTreatments: ["hns_inspire", "surgical_uppp"],
      alternativeLabels: ["HNS (Inspire) — if moderate OSA and CPAP intolerant", "UPPP — if palatal obstruction identified"],
      hnsEligible: hnsResult.eligible,
      hnsCriteria: hnsResult.criteria,
      hnsContraindications: hnsResult.contraindications,
      oralApplianceSuitable: true,
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: [
        ...warnings,
        "Oral appliance efficacy: inferior to CPAP for severe OSA — confirm efficacy with follow-up sleep study",
        "Side effects: temporomandibular joint pain, tooth soreness — monitor and adjust",
      ],
      nextSteps,
      rationale: "Oral appliance (MAD) is recommended for mild-moderate OSA or CPAP-intolerant patients. Efficacy: 50-60% responder rate. Inferior to CPAP for severe OSA.",
      evidenceLevel: "Strong",
      guidelineSource: "AASM 2024 (PMID: 38692572)",
    };
  }

  // Surgical options for CPAP intolerant with anatomic obstruction
  if (input.anatomicObstruction === "palatal" && input.tonsilSize >= 3) {
    nextSteps.push("Tonsillectomy + UPPP: most effective for large tonsils (grade 3-4) with palatal obstruction");
    nextSteps.push("Pre-operative DISE to confirm palatal obstruction pattern");
    return {
      primaryTreatment: "surgical_tonsillectomy",
      primaryLabel: "Tonsillectomy + UPPP (Large Tonsils, Palatal Obstruction)",
      alternativeTreatments: ["hns_inspire", "oral_appliance"],
      alternativeLabels: ["HNS (Inspire) — if DISE shows no CCC", "Oral Appliance (MAD)"],
      hnsEligible: hnsResult.eligible,
      hnsCriteria: hnsResult.criteria,
      hnsContraindications: hnsResult.contraindications,
      oralApplianceSuitable,
      surgicalProcedure: "Tonsillectomy + Uvulopalatopharyngoplasty (UPPP)",
      surgicalRationale: "Tonsillectomy + UPPP: 60-80% success rate for grade 3-4 tonsils. Most effective surgical option for palatal obstruction with large tonsils.",
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: warnings,
      nextSteps,
      rationale: "Tonsillectomy + UPPP is recommended for CPAP-intolerant OSA with grade 3-4 tonsils and palatal obstruction. Success rate 60-80%.",
      evidenceLevel: "Moderate",
      guidelineSource: "AAO-HNS 2019 (PMID: 30920341); AASM 2024 (PMID: 38692572)",
    };
  }

  // MMA for retrognathia or failed UPPP
  if (input.anatomicObstruction === "retrognathia" || input.priorUPPP) {
    nextSteps.push("Maxillomandibular advancement (MMA): most effective surgical procedure for OSA — 85-90% success rate");
    nextSteps.push("Pre-operative cephalometry and orthodontic evaluation");
    nextSteps.push("Requires 6-8 week jaw wiring — significant recovery period");
    return {
      primaryTreatment: "surgical_mma",
      primaryLabel: "Maxillomandibular Advancement (MMA) — Highest Surgical Success Rate",
      alternativeTreatments: ["hns_inspire", "oral_appliance"],
      alternativeLabels: ["HNS (Inspire) — if DISE eligible", "Oral Appliance (MAD)"],
      hnsEligible: hnsResult.eligible,
      hnsCriteria: hnsResult.criteria,
      hnsContraindications: hnsResult.contraindications,
      oralApplianceSuitable,
      surgicalProcedure: "Maxillomandibular Advancement (MMA)",
      surgicalRationale: "MMA: 85-90% success rate (AHI reduction ≥50%), most effective surgical procedure for OSA. Indicated for retrognathia or failed UPPP.",
      severityLabel,
      cvRisk: cvRiskResult.risk,
      cvRiskRationale: cvRiskResult.rationale,
      keyWarnings: [...warnings, "MMA: significant surgical procedure with 6-8 week recovery — ensure patient is well-informed"],
      nextSteps,
      rationale: "MMA is the most effective surgical procedure for OSA (85-90% success rate). Indicated for retrognathia or failed UPPP.",
      evidenceLevel: "Strong",
      guidelineSource: "AASM 2024 (PMID: 38692572); AAO-HNS 2019 (PMID: 30920341)",
    };
  }

  // Default: combination therapy / multidisciplinary
  return {
    primaryTreatment: "combination_therapy",
    primaryLabel: "Combination Therapy (CPAP + Adjunctive Measures)",
    alternativeTreatments: ["hns_inspire", "oral_appliance"],
    alternativeLabels: ["HNS (Inspire) — if CPAP intolerant and eligible", "Oral Appliance (MAD)"],
    cpapRecommendation: "Re-trial CPAP with improved adherence support: desensitization protocol, cognitive behavioral therapy for CPAP, different mask interface",
    hnsEligible: hnsResult.eligible,
    hnsCriteria: hnsResult.criteria,
    hnsContraindications: hnsResult.contraindications,
    oralApplianceSuitable,
    severityLabel,
    cvRisk: cvRiskResult.risk,
    cvRiskRationale: cvRiskResult.rationale,
    keyWarnings: warnings,
    nextSteps: [
      "Sleep medicine referral for comprehensive OSA management",
      "CPAP re-trial with behavioral support and mask optimization",
      "Weight loss: 10% weight loss reduces AHI by ~26%",
      "Consider HNS (Inspire) evaluation if CPAP intolerant",
    ],
    rationale: "Complex OSA management: combination therapy and multidisciplinary approach recommended.",
    evidenceLevel: "Moderate",
    guidelineSource: "AASM 2024 (PMID: 38692572)",
  };
}

// ─── Utility Functions ─────────────────────────────────────────────────────────

export function getTreatmentColor(treatment: OSATreatment): string {
  switch (treatment) {
    case "cpap_first_line":
    case "cpap_optimization": return "bg-blue-900/40 border-blue-600 text-blue-300";
    case "oral_appliance": return "bg-teal-900/40 border-teal-600 text-teal-300";
    case "hns_inspire": return "bg-emerald-900/40 border-emerald-600 text-emerald-300";
    case "surgical_uppp":
    case "surgical_mma":
    case "surgical_nasal":
    case "surgical_tonsillectomy": return "bg-violet-900/40 border-violet-600 text-violet-300";
    case "positional_therapy": return "bg-yellow-900/40 border-yellow-600 text-yellow-300";
    case "weight_loss": return "bg-green-900/40 border-green-600 text-green-300";
    case "combination_therapy": return "bg-indigo-900/40 border-indigo-600 text-indigo-300";
    case "observation": return "bg-slate-800/50 border-slate-600 text-slate-400";
    default: return "bg-slate-800/50 border-slate-600 text-slate-400";
  }
}

export function getCVRiskColor(risk: "low" | "moderate" | "high"): string {
  switch (risk) {
    case "low": return "text-emerald-400";
    case "moderate": return "text-yellow-400";
    case "high": return "text-red-400";
  }
}
